import { createCluster } from 'redis';

const cluster = createCluster({
  rootNodes: [
    { url: 'redis://localhost:7000' },
    { url: 'redis://localhost:7001' },
    { url: 'redis://localhost:7002' },
  ],
});

await cluster.connect();

// Commands route to correct node automatically
await cluster.set('user:1', 'Alice');  // goes to node holding slot for 'user:1'
await cluster.get('user:1');           // goes to same node

// MGET works only if all keys are on same node
// Use hash tags to co-locate keys
await cluster.set('{user:1}.name', 'Alice');
await cluster.set('{user:1}.email', 'alice@ex.com');
await cluster.mGet(['{user:1}.name', '{user:1}.email']);  // same slot, works!
